import{b as o,O as t,g as a,j as p}from"./chunks/framework.DcaUmd3X.js";const s=JSON.parse('{"title":"人类简史：从动物到上帝","description":"","frontmatter":{},"headers":[],"relativePath":"reading/digital/sapiens/index.md","filePath":"读书感悟/电子书架/17.人类简史：从动物到上帝.md","lastUpdated":1781614933000}'),l={name:"reading/digital/sapiens/index.md"};function c(r,e,i,_,d,n){return t(),a("div",null,[...e[0]||(e[0]=[p('<h1 id="人类简史-从动物到上帝" tabindex="-1">人类简史：从动物到上帝 <a class="header-anchor" href="#人类简史-从动物到上帝" aria-label="Permalink to &quot;人类简史：从动物到上帝&quot;">​</a></h1><p><code>尤瓦尔·赫拉利</code> <code>世界史</code></p><h2 id="书摘" tabindex="-1">书摘 <a class="header-anchor" href="#书摘" aria-label="Permalink to &quot;书摘&quot;">​</a></h2><blockquote><p>📌 所谓投资可以分成很多种：扩建工厂、从事科学研究、开发新产品。但不论如何，重点就是要增加产量，转为更多的利润。</p></blockquote><blockquote><p>📌 只要有了活下去的理由，几乎什么都能够忍受。生活有意义，就算</p></blockquote><blockquote><p>📌 在困境中也能甘之如饴；生活无意义，就算在顺境中也度日如年。</p></blockquote><blockquote><p>📌 我觉得好的，就是好的。我觉得坏的，就是坏的。”</p></blockquote><h2 id="书评" tabindex="-1">书评 <a class="header-anchor" href="#书评" aria-label="Permalink to &quot;书评&quot;">​</a></h2><blockquote><p>💭 跟洗脑差不多，通过潜移默化的改变人们心中的信仰，随着时间的推移，变得坚不可摧</p><p>📌 人类几乎从出生到死亡都被种种虚构的故事和概念围绕，让他们以特定的方式思考，以特定的标准行事，想要特定的东西，也遵守特定的规范。</p></blockquote><blockquote><p>💭 认知革命的影响直到今天仍然在潜移默化的影响着我们</p><p>📌 和完全陌生的人合作成了家常便饭，而且还可能觉得这些人就像是“兄弟”或是“朋友”。</p></blockquote><blockquote><p>💭 烦恼在于想的太多</p><p>📌 一切苦难并非来自噩运、社会不公或是神祇的任性，而是出于每个人自己心中的思想模式。</p></blockquote><blockquote><p>💭 对想要的东西或事情的期望值不到十分确定的时候不要拉的太高，遇到悲伤不愉快的事情想办法解决，开导自己</p><p>📌 在事物带来快乐或痛苦的时候，重点是要看清事物的本质，而不是着重在它带来的感受，于是就能不再为此所困。</p></blockquote><blockquote><p>💭 对于漫漫时间长河中，我们也是一样的渺小</p><p>📌 历史就这样从一个岔路走到下一个岔路，选择走某条道路而非另一条的原因总是神秘而不得而知。</p></blockquote><blockquote><p>💭 也可以说是资本主义推动着社会的发展</p><p>📌 不论是科学还是帝国，它们能够迅速崛起，背后都还潜藏着一股特别重要的力量：资本主义。要不是因为商人想赚钱，哥伦布就不会抵达美洲，库克船长就不会抵达澳大利亚，阿姆斯特朗也就没办法在月球上跨出他那重要的一小步。</p></blockquote>',14)])])}const b=o(l,[["render",c]]);export{s as __pageData,b as default};
